import React, { useState } from 'react';
import { Box, Button, Data, DataFilters, Grommet, Layer } from 'grommet';
import { DATA } from '../../DataTable/stories/data';

const CustomDataFilters = () => {
  const [showLayer, setShowLayer] = useState(false);

  return (
    <Grommet>
      <Box fill align="center" justify="start" pad="large">
        <Data data={DATA}>
          <Button label="Show Filters" onClick={() => setShowLayer(true)} />
          {showLayer && (
            <Layer
              onEsc={() => setShowLayer(false)}
              onClickOutside={() => setShowLayer(false)}
            >
              <Box pad="medium">
                <DataFilters />
                <Button label="Close" onClick={() => setShowLayer(false)} />
              </Box>
            </Layer>
          )}
        </Data>
      </Box>
    </Grommet>
  );
};

export default CustomDataFilters;
